"""字段级破坏性变更识别。

输入两个同一 Schema 标识下的 JSON Schema 文档（基线版本、候选版本）与显式
字段重命名映射，产出确定性的字段级变更报告。

变更种类（``change_kind``）：
  * ``added``            新增字段（非必填兼容 / 必填破坏）
  * ``deleted``          删除字段（破坏）
  * ``modified``         结构定义变化（按收窄/放宽判定）
  * ``required_added``   既有字段新增必填约束（破坏）
  * ``required_removed`` 既有字段解除必填约束（兼容）
  * ``rename``           显式声明的重命名（整棵子树按一次 rename 计入）
  * ``metadata``         仅标题/描述/注释变化（元数据变更）

兼容结论（``compatibility``）：``breaking`` / ``compatible`` / ``metadata``。
"""

from __future__ import annotations

import hashlib
import json
from typing import Any

from . import limits, pointer as ptr, schema_fields as sf
from .errors import ImpactAnalysisTooLarge
from .registry import Registry

RENAMED = "rename"
ADDED = "added"
DELETED = "deleted"
MODIFIED = "modified"
REQUIRED_ADDED = "required_added"
REQUIRED_REMOVED = "required_removed"
METADATA = "metadata"

BREAKING = "breaking"
COMPATIBLE = "compatible"
METADATA_COMPAT = "metadata"


def _required_set(fields: dict[str, sf.Field]) -> set[str]:
    """收集文档内全部被标记为必填的字段路径（已合并 allOf 的 required）。"""
    out: set[str] = set()
    for f in fields.values():
        out.update(f.required_paths)
    return out


def _summary(schema: dict) -> dict[str, Any]:
    # required 是父节点对子字段的约束，不放进字段自身摘要。
    return {k: v for k, v in sf.summary(schema).items() if k != "required"}


def validate_renames(
    renames: list | None,
    old_fields: dict[str, sf.Field],
    new_fields: dict[str, sf.Field],
) -> list[tuple[str, str]]:
    """校验并规范化重命名映射，失败时抛 :class:`SchemaComparisonInvalid`。"""
    from .errors import SchemaComparisonInvalid

    if renames is None:
        return []
    if not isinstance(renames, list):
        raise SchemaComparisonInvalid(
            "重命名映射必须是 [{from, to}, ...] 列表",
            details={"reason": "renames_not_list"},
        )

    pairs: list[tuple[str, str]] = []
    for i, item in enumerate(renames):
        if isinstance(item, dict):
            src, dst = item.get("from"), item.get("to")
        elif isinstance(item, (tuple, list)) and len(item) == 2:
            src, dst = item[0], item[1]
        else:
            src = dst = None
        if not isinstance(src, str) or not isinstance(dst, str) or not src or not dst:
            raise SchemaComparisonInvalid(
                f"第 {i} 条重命名映射必须包含非空字符串 from 与 to",
                details={"reason": "rename_invalid", "index": i},
            )
        pairs.append((src, dst))

    # 1) 起点/终点必须存在于对应版本。
    for src, dst in pairs:
        if src not in old_fields:
            raise SchemaComparisonInvalid(
                f"重命名起点 {src} 在基线版本中不存在",
                details={"reason": "rename_from_not_found", "path": src},
            )
        if dst not in new_fields:
            raise SchemaComparisonInvalid(
                f"重命名终点 {dst} 在候选版本中不存在",
                details={"reason": "rename_to_not_found", "path": dst},
            )

    # 2) 同一路径不得被重复映射（任一端点出现两次，或起点等于终点）。
    seen: set[str] = set()
    for src, dst in pairs:
        for ep in (src, dst):
            if ep in seen:
                raise SchemaComparisonInvalid(
                    f"路径 {ep} 在重命名映射中被重复使用",
                    details={"reason": "rename_duplicate", "path": ep},
                )
            seen.add(ep)

    # 端点两两之间子树不得重叠，否则同一路径被隐式映射两次。
    ordered = sorted(seen, key=lambda p: ptr.parse(p))
    for a, b in zip(ordered, ordered[1:]):
        if ptr.is_under(a, b):
            raise SchemaComparisonInvalid(
                f"重命名端点 {a} 与 {b} 的子树重叠，映射不明确",
                details={"reason": "rename_overlapping", "paths": [a, b]},
            )

    # 3) 跨版本一致性：起点不应仍在候选版本、终点不应已在基线版本。
    for src, dst in pairs:
        if src in new_fields:
            raise SchemaComparisonInvalid(
                f"重命名起点 {src} 仍存在于候选版本，映射跨版本不一致",
                details={"reason": "rename_cross_version_inconsistent", "path": src},
            )
        if dst in old_fields:
            raise SchemaComparisonInvalid(
                f"重命名终点 {dst} 已存在于基线版本，映射跨版本不一致",
                details={"reason": "rename_cross_version_inconsistent", "path": dst},
            )

    return pairs


def _entry(
    change_kind: str,
    compatibility: str,
    old_path: str | None,
    new_path: str | None,
    old_schema: dict | None,
    new_schema: dict | None,
    impacts: dict | None,
) -> dict[str, Any]:
    return {
        "path": new_path if new_path is not None else old_path,
        "old_path": old_path,
        "new_path": new_path,
        "old_summary": _summary(old_schema) if old_schema is not None else None,
        "new_summary": _summary(new_schema) if new_schema is not None else None,
        "change_kind": change_kind,
        "compatibility": compatibility,
        "direct_assets": list(impacts["direct_assets"]) if impacts else [],
        "transitive_assets": list(impacts["transitive_assets"]) if impacts else [],
    }


def _compare_matched(
    old_field: sf.Field, new_field: sf.Field, old_required: bool, new_required: bool
) -> tuple[str, str] | None:
    """比较两侧对齐的同字段，返回 (change_kind, compatibility) 或 None。"""
    old_s, new_s = old_field.schema, new_field.schema
    struct_changed = sf.structural_signature(old_s) != sf.structural_signature(new_s)

    if not struct_changed:
        if old_required == new_required:
            annotation_changed = (
                sf.annotation_signature(old_s) != sf.annotation_signature(new_s)
            )
            return (METADATA, METADATA_COMPAT) if annotation_changed else None
        if new_required:
            return REQUIRED_ADDED, BREAKING
        return REQUIRED_REMOVED, COMPATIBLE

    verdict = sf.classify_pair(old_s, new_s)
    if new_required and not old_required:
        verdict = BREAKING  # 结构变化与新增必填同时发生，取更严格结论
    return MODIFIED, verdict


def build_report(
    registry: Registry,
    name: str,
    baseline_version: str,
    candidate_document: Any,
    candidate_version: str | None,
    renames: list | None,
) -> dict[str, Any]:
    """构造字段级变更报告（不读取候选注册内容、不改动任何注册数据）。"""
    from .impact import analyze_field

    old_doc = registry.get_schema(name, baseline_version).document

    old_fields = sf.expand(old_doc)
    new_fields = sf.expand(candidate_document)
    if len(old_fields) > limits.MAX_FIELDS or len(new_fields) > limits.MAX_FIELDS:
        raise ImpactAnalysisTooLarge(
            "分析对象字段数量超过公开限制",
            details={
                "reason": "fields_exceeded",
                "limit": limits.MAX_FIELDS,
                "baseline_fields": len(old_fields),
                "candidate_fields": len(new_fields),
            },
        )
    old_required = _required_set(old_fields)
    new_required = _required_set(new_fields)

    pairs = validate_renames(renames, old_fields, new_fields)
    rename_srcs = dict(pairs)
    rename_dsts = {d: s for s, d in pairs}

    def in_rename_subtree(path: str, roots: dict[str, str]) -> str | None:
        """返回包含该路径的重命名根（路径按段序排序，最近的根唯一）。"""
        segs = ptr.parse(path)
        best = None
        for root in roots:
            rsegs = ptr.parse(root)
            if len(rsegs) <= len(segs) and segs[: len(rsegs)] == rsegs:
                if best is None or len(rsegs) > len(ptr.parse(best)):
                    best = root
        return best

    # 重命名子树对齐：old 后缀路径 -> new 后缀路径（仅当两侧都存在）。
    aligned_old: dict[str, str] = {}
    aligned_new: dict[str, str] = {}
    for src, dst in pairs:
        src_segs, dst_segs = ptr.parse(src), ptr.parse(dst)
        for p in old_fields:
            psegs = ptr.parse(p)
            if len(psegs) <= len(src_segs) or psegs[: len(src_segs)] != src_segs:
                continue
            q = ptr.format(dst_segs + psegs[len(src_segs) :])
            if q in new_fields:
                aligned_old[p] = q
                aligned_new[q] = p

    changes: list[dict[str, Any]] = []

    def impacts_for(old_path: str) -> dict:
        return analyze_field(registry, name, baseline_version, old_path)

    # 1) 重命名根：每条映射恰好一条 rename（不再计删除+新增）。
    for src, dst in sorted(pairs):
        changes.append(
            _entry(
                RENAMED,
                BREAKING,
                src,
                dst,
                old_fields[src].schema,
                new_fields[dst].schema,
                impacts_for(src),
            )
        )

    # 2) 旧侧：子树对齐字段做配对比较；其余旧侧独有路径为 deleted。
    for p in sorted(old_fields, key=lambda x: ptr.parse(x)):
        if p in rename_srcs:
            continue
        if in_rename_subtree(p, rename_srcs) is not None:
            q = aligned_old.get(p)
            if q is None:
                changes.append(
                    _entry(
                        DELETED, BREAKING, p, None,
                        old_fields[p].schema, None, impacts_for(p),
                    )
                )
            else:
                decision = _compare_matched(
                    old_fields[p], new_fields[q], p in old_required, q in new_required
                )
                if decision is not None:
                    changes.append(
                        _entry(
                            decision[0], decision[1], p, q,
                            old_fields[p].schema, new_fields[q].schema,
                            impacts_for(p),
                        )
                    )
            continue
        if p in new_fields:
            continue  # 公共路径，第 4 步处理
        changes.append(
            _entry(
                DELETED, BREAKING, p, None,
                old_fields[p].schema, None, impacts_for(p),
            )
        )

    # 3) 新侧：重命名子树中未覆盖的新路径与其余新侧独有路径为 added。
    for q in sorted(new_fields, key=lambda x: ptr.parse(x)):
        if q in rename_dsts:
            continue
        if in_rename_subtree(q, rename_dsts) is not None:
            if q in aligned_new:
                continue  # 已在第 2 步配对比较
        elif q in old_fields:
            continue  # 公共路径，第 4 步处理
        changes.append(
            _entry(
                ADDED,
                BREAKING if q in new_required else COMPATIBLE,
                None,
                q,
                None,
                new_fields[q].schema,
                None,
            )
        )

    # 4) 非重命名公共路径。
    for p in sorted(old_fields, key=lambda x: ptr.parse(x)):
        if p in rename_srcs or in_rename_subtree(p, rename_srcs) is not None:
            continue
        if p not in new_fields:
            continue
        decision = _compare_matched(
            old_fields[p], new_fields[p], p in old_required, p in new_required
        )
        if decision is not None:
            changes.append(
                _entry(
                    decision[0], decision[1], p, p,
                    old_fields[p].schema, new_fields[p].schema, impacts_for(p),
                )
            )

    if len(changes) > limits.MAX_CHANGES:
        raise ImpactAnalysisTooLarge(
            "变更条目数量超过公开限制",
            details={"reason": "changes_exceeded", "limit": limits.MAX_CHANGES},
        )

    # 确定性排序：按展示路径段、路径文本、变更种类。
    changes.sort(
        key=lambda e: (
            ptr.parse(e["path"]),
            e["path"],
            e["change_kind"],
            e["old_path"] or "",
        )
    )

    counts = {BREAKING: 0, COMPATIBLE: 0, METADATA_COMPAT: 0}
    for e in changes:
        counts[e["compatibility"]] += 1

    canonical = json.dumps(
        {
            "schema": name,
            "baseline_version": baseline_version,
            "candidate_version": candidate_version,
            "candidate_document": candidate_document,
            "renames": sorted(pairs),
        },
        sort_keys=True,
        ensure_ascii=False,
        separators=(",", ":"),
    )
    report_id = hashlib.sha256(canonical.encode("utf-8")).hexdigest()[:16]

    return {
        "report_id": report_id,
        "schema": name,
        "baseline_version": baseline_version,
        "candidate_version": candidate_version,
        "renames": [{"from": s, "to": d} for s, d in sorted(pairs)],
        "summary": {
            "total": len(changes),
            "breaking": counts[BREAKING],
            "compatible": counts[COMPATIBLE],
            "metadata": counts[METADATA_COMPAT],
        },
        "changes": changes,
    }

"""字段级影响分析。

直接影响：资产的字段引用与目标字段 ``(schema, version, path)`` 精确相等。
传递影响：从资产引用的具体字段出发，沿跨 Schema ``$ref`` 边正向解析，
若能到达目标字段（精确相等、或祖先/后代包含关系），即构成传递命中。

正向解析从资产引用的 *具体* 路径出发，路径长度随跨边跳数只减不增，因此
即使 Schema 之间存在根级引用环，状态空间也是有限的。传递结果按稳定标识
``(资产, schema, version, 引用路径)`` 去重。
"""

from __future__ import annotations

from dataclasses import dataclass

from . import limits, pointer as ptr
from .errors import ImpactAnalysisTooLarge
from .registry import Registry, RefEdge


@dataclass(frozen=True)
class Reach:
    schema: str
    version: str
    path: str


def _related(a: str, b: str) -> bool:
    return a == b or ptr.is_under(a, b) or ptr.is_under(b, a)


def _build_outgoing(registry: Registry) -> dict[tuple[str, str], list[RefEdge]]:
    outgoing: dict[tuple[str, str], list[RefEdge]] = {}
    for edge in registry.all_edges():
        outgoing.setdefault((edge.src_schema, edge.src_version), []).append(edge)
    for edges in outgoing.values():
        edges.sort(
            key=lambda e: (e.dst_schema, e.dst_version, e.src_path, e.dst_path)
        )
    return outgoing


def forward_reach(
    registry: Registry,
    schema: str,
    version: str,
    path: str,
    outgoing: dict[tuple[str, str], list[RefEdge]] | None = None,
    cache: dict[tuple[str, str, str], list[Reach]] | None = None,
) -> list[Reach]:
    """从一个具体字段出发正向解析跨 Schema 引用，返回可到达的全部字段。

    每条出边满足：边的源路径与当前路径相等，或是当前路径的祖先
    （引用了包含当前字段的子树）；目标侧路径按后缀对齐。
    """
    if cache is not None:
        cached = cache.get((schema, version, path))
        if cached is not None:
            return cached
    if outgoing is None:
        outgoing = _build_outgoing(registry)

    start = Reach(schema, version, path)
    reached: dict[Reach, None] = {start: None}
    queue: list[tuple[Reach, int]] = [(start, 0)]
    edges_walked = 0

    while queue:
        state, depth = queue.pop(0)
        if depth >= limits.MAX_IMPACT_DEPTH:
            raise ImpactAnalysisTooLarge(
                "影响链深度超过公开限制",
                details={
                    "reason": "depth_exceeded",
                    "limit": limits.MAX_IMPACT_DEPTH,
                    "schema": state.schema,
                    "version": state.version,
                    "path": state.path,
                },
            )
        for edge in outgoing.get((state.schema, state.version), ()):
            sp, cp = ptr.parse(edge.src_path), ptr.parse(state.path)
            if not (len(sp) <= len(cp) and cp[: len(sp)] == sp):
                continue
            edges_walked += 1
            if edges_walked > limits.MAX_IMPACT_VISITED:
                raise ImpactAnalysisTooLarge(
                    "影响链引用边数量超过公开限制",
                    details={"reason": "edges_exceeded", "limit": limits.MAX_IMPACT_VISITED},
                )
            suffix = cp[len(sp) :]
            mapped = Reach(
                edge.dst_schema,
                edge.dst_version,
                ptr.format(list(ptr.parse(edge.dst_path)) + list(suffix)),
            )
            if mapped in reached:
                continue
            reached[mapped] = None
            queue.append((mapped, depth + 1))

    del reached[start]
    result = sorted(reached.keys(), key=lambda r: (r.schema, r.version, r.path))
    if cache is not None:
        cache[(schema, version, path)] = result
    return result


def analyze_field(registry: Registry, schema: str, version: str, path: str) -> dict:
    """返回单个字段的影响资产：直接 + 传递（各自稳定排序、去重）。"""
    registry.get_schema(schema, version)

    direct: dict[str, dict] = {}
    transitive_map: dict[tuple[str, str, str, str], dict] = {}
    outgoing = _build_outgoing(registry)
    reach_cache: dict[tuple[str, str, str], list[Reach]] = {}

    for asset in registry.all_assets():
        for ref in asset.refs:
            if ref.schema == schema and ref.version == version:
                if ref.path == path:
                    direct.setdefault(
                        asset.id,
                        {"asset_id": asset.id, "name": asset.name, "kind": asset.kind},
                    )
                    continue

            # 传递：从资产引用的具体字段正向解析到目标字段。
            reachable = forward_reach(
                registry, ref.schema, ref.version, ref.path, outgoing, reach_cache
            )
            matched = [r for r in reachable if r.schema == schema and r.version == version
                       and _related(r.path, path)]
            if not matched:
                continue
            key = (asset.id, ref.schema, ref.version, ref.path)
            entry = transitive_map.get(key)
            if entry is None:
                entry = {
                    "asset_id": asset.id,
                    "name": asset.name,
                    "kind": asset.kind,
                    "schema": ref.schema,
                    "version": ref.version,
                    "path": ref.path,
                    "matched_paths": [],
                }
                transitive_map[key] = entry
            for r in matched:
                if r.path not in entry["matched_paths"]:
                    entry["matched_paths"].append(r.path)

    transitive = list(transitive_map.values())
    for entry in transitive:
        entry["matched_paths"].sort(key=lambda p: (ptr.parse(p), p))

    if len(direct) + len(transitive) > limits.MAX_IMPACT_ASSETS:
        raise ImpactAnalysisTooLarge(
            "影响资产数量超过公开限制",
            details={"reason": "assets_exceeded", "limit": limits.MAX_IMPACT_ASSETS},
        )

    return {
        "schema": schema,
        "version": version,
        "path": path,
        "direct_assets": [direct[k] for k in sorted(direct)],
        "transitive_assets": sorted(
            transitive,
            key=lambda a: (a["asset_id"], a["schema"], a["version"], a["path"]),
        ),
    }

"""注册簿：Schema 版本、目录资产与跨 Schema 引用关系。

注册内容不可变：任何读取都返回深拷贝，比较、影响分析和检索都无法改动
既有注册结果、版本关系与资产依赖关系。

跨 Schema 引用约定：``$ref`` 写作 ``"<SchemaName>@<version>#<JSONPointer>"``，
例如 ``"Address@1.0#/properties/street"``；``#`` 后为空表示引用文档根。
文档内引用沿用标准 ``"#/..."`` 形式。
"""

from __future__ import annotations

import copy
import re
from dataclasses import dataclass
from typing import Any

from .errors import AlreadyExistsError, NotFoundError
from . import pointer as ptr
from .schema_fields import expand as _expand_fields

_REF_RE = re.compile(r"^(?P<name>[^@#/\s]+)@(?P<version>[^@#\s]+)#(?P<pointer>.*)$")
_NAME_RE = re.compile(r"^[A-Za-z0-9_.\-]+$")


def validate_name(name: str, *, what: str = "名称") -> None:
    if not isinstance(name, str) or not name or not _NAME_RE.match(name):
        raise ValueError(f"非法{what}: {name!r}（只允许字母、数字、_、.、-）")


@dataclass(frozen=True)
class SchemaVersion:
    name: str
    version: str
    document: Any
    title: str | None


@dataclass(frozen=True)
class FieldRef:
    """资产对某 Schema 某版本某字段路径的直接引用。"""

    schema: str
    version: str
    path: str  # JSON Pointer，"" 表示根


@dataclass(frozen=True)
class Asset:
    id: str
    name: str
    kind: str
    refs: tuple[FieldRef, ...]


@dataclass(frozen=True)
class RefEdge:
    """一条跨 Schema ``$ref`` 边：src 字段定义引用了 dst 字段节点。"""

    src_schema: str
    src_version: str
    src_path: str
    dst_schema: str
    dst_version: str
    dst_path: str


def parse_external_ref(ref: str) -> tuple[str, str, str] | None:
    """解析跨 Schema 引用；非此外部形式返回 ``None``。"""
    m = _REF_RE.match(ref)
    if not m:
        return None
    return m.group("name"), m.group("version"), m.group("pointer")


def extract_ref_edges(name: str, version: str, document: Any) -> list[RefEdge]:
    """提取文档内全部跨 Schema 引用边（原始文档指针，按出现顺序排序）。

    指针在注册时再结合两端文档解析为逻辑字段路径。
    """
    edges: list[RefEdge] = []

    def walk(node: Any, path: str, seen: frozenset[int]) -> None:
        if isinstance(node, bool) or not isinstance(node, (dict, list)):
            return
        if id(node) in seen:
            return
        seen = seen | {id(node)}
        if isinstance(node, dict):
            ref = node.get("$ref")
            if isinstance(ref, str):
                parsed = parse_external_ref(ref)
                if parsed is not None:
                    dst_name, dst_version, fragment = parsed
                    if fragment and not fragment.startswith("/"):
                        fragment = "/" + fragment
                    edges.append(
                        RefEdge(name, version, path, dst_name, dst_version, fragment)
                    )
            for k in sorted(node.keys()):
                walk(node[k], path + "/" + _escape(k) if path else "/" + _escape(k), seen)
        else:
            for i, v in enumerate(node):
                walk(v, f"{path}/{i}" if path else f"/{i}", seen)

    walk(document, "", frozenset())
    edges.sort(key=lambda e: (e.src_path, e.dst_schema, e.dst_version, e.dst_path))
    return edges


def _escape(token: str) -> str:
    return token.replace("~", "~0").replace("/", "~1")


class Registry:
    def __init__(self) -> None:
        self._schemas: dict[tuple[str, str], SchemaVersion] = {}
        # name -> 按注册顺序保存的版本列表
        self._versions: dict[str, list[str]] = {}
        self._assets: dict[str, Asset] = {}
        self._edges: dict[tuple[str, str], tuple[RefEdge, ...]] = {}

    # ------------------------------------------------------------------ schema
    def register_schema(self, name: str, version: str, document: Any) -> SchemaVersion:
        validate_name(name, what="Schema 名称")
        validate_name(version, what="版本号")
        key = (name, version)
        if key in self._schemas:
            raise AlreadyExistsError(
                f"Schema {name}@{version} 已注册，注册内容不可覆盖",
                details={"schema": name, "version": version},
            )
        # 跨 Schema 引用允许前向（目标稍后注册），因此引用环也可注册；
        # 目标缺失或目标字段不存在时，影响传播自然不会产生命中。
        raw_edges = extract_ref_edges(name, version, document)
        edges: list[RefEdge] = []
        for e in raw_edges:
            dst_record = self._schemas.get((e.dst_schema, e.dst_version))
            dst_raw = e.dst_path if e.dst_path else ""
            if dst_record is not None:
                dst_logical = ptr.resolve_logical(dst_record.document, dst_raw)
                if dst_logical is None or dst_logical not in _expand_fields(dst_record.document):
                    # 目标已注册但字段不存在：属于确定的非法引用。
                    raise NotFoundError(
                        f"跨 Schema 引用 {e.dst_schema}@{e.dst_version}{dst_raw} 的目标字段不存在",
                        details={
                            "schema": e.dst_schema,
                            "version": e.dst_version,
                            "path": dst_raw,
                        },
                    )
                final_dst = dst_logical
            else:
                final_dst = ptr.normalize_field_pointer(dst_raw)
            src_logical = ptr.resolve_logical(document, e.src_path)
            edges.append(
                RefEdge(
                    name,
                    version,
                    src_logical or ptr.normalize_field_pointer(e.src_path),
                    e.dst_schema,
                    e.dst_version,
                    final_dst,
                )
            )
        edges.sort(key=lambda x: (x.src_path, x.dst_schema, x.dst_version, x.dst_path))
        title = None
        if isinstance(document, dict):
            t = document.get("title")
            title = t if isinstance(t, str) else None
        record = SchemaVersion(name, version, copy.deepcopy(document), title)
        self._schemas[key] = record
        self._versions.setdefault(name, []).append(version)
        self._edges[key] = tuple(edges)
        return record

    def get_schema(self, name: str, version: str) -> SchemaVersion:
        key = (name, version)
        if key not in self._schemas:
            raise NotFoundError(
                f"Schema {name}@{version} 不存在",
                details={"schema": name, "version": version},
            )
        return self._schemas[key]

    def has_schema(self, name: str, version: str) -> bool:
        return (name, version) in self._schemas

    def schema_document(self, name: str, version: str) -> Any:
        return copy.deepcopy(self.get_schema(name, version).document)

    def list_versions(self, name: str) -> list[str]:
        if name not in self._versions:
            raise NotFoundError(f"Schema {name} 不存在", details={"schema": name})
        return list(self._versions[name])

    def edges(self, name: str, version: str) -> tuple[RefEdge, ...]:
        return self._edges.get((name, version), ())

    def all_edges(self) -> list[RefEdge]:
        out: list[RefEdge] = []
        for key in sorted(self._edges):
            out.extend(self._edges[key])
        return out

    def all_schemas(self) -> list[SchemaVersion]:
        return [self._schemas[k] for k in sorted(self._schemas)]

    def registered_pairs(self) -> list[tuple[str, str]]:
        """按全局注册顺序返回全部 ``(名称, 版本)``。"""
        return list(self._schemas.keys())

    def logical_path_exists(self, schema: str, version: str, path: str) -> bool:
        """判断逻辑字段路径是否可达（含沿跨 Schema ``$ref`` 跳转解析）。"""
        return self._logical_path_exists(
            schema, version, path, frozenset({(schema, version)})
        )

    def _logical_path_exists(
        self, schema: str, version: str, path: str, stack: frozenset[tuple[str, str]]
    ) -> bool:
        """判断逻辑字段路径是否可达，沿跨 Schema ``$ref`` 边跳转解析。"""
        if (schema, version) not in self._schemas:
            return False
        document = self._schemas[(schema, version)].document
        valid_paths = _expand_fields(document)
        if path in valid_paths:
            return True

        target_segs = ptr.parse(path)
        # 选择最长的、能覆盖目标路径前缀的出边。
        best = None
        for edge in self._edges.get((schema, version), ()):  # type: RefEdge
            esegs = ptr.parse(edge.src_path)
            if len(esegs) <= len(target_segs) and target_segs[: len(esegs)] == esegs:
                if best is None or len(esegs) > len(ptr.parse(best.src_path)):
                    best = edge
        if best is None:
            return False
        dst_key = (best.dst_schema, best.dst_version)
        if dst_key in stack:
            return False
        suffix = target_segs[len(ptr.parse(best.src_path)) :]
        resolved = ptr.format(list(ptr.parse(best.dst_path)) + list(suffix))
        return self._logical_path_exists(
            best.dst_schema, best.dst_version, resolved, stack | {dst_key}
        )

    # ------------------------------------------------------------------- asset
    def register_asset(
        self,
        asset_id: str,
        name: str,
        kind: str,
        refs: list[FieldRef] | list[dict] | None = None,
    ) -> Asset:
        validate_name(asset_id, what="资产标识")
        if not isinstance(name, str) or not name:
            raise ValueError("资产名称必须是非空字符串")
        if not isinstance(kind, str) or not kind:
            raise ValueError("资产类型必须是非空字符串")
        if asset_id in self._assets:
            raise AlreadyExistsError(
                f"资产 {asset_id} 已注册", details={"asset": asset_id}
            )

        normalized: list[FieldRef] = []
        seen: set[tuple[str, str, str]] = set()
        for raw in refs or []:
            if isinstance(raw, FieldRef):
                r = raw
            else:
                r = FieldRef(raw["schema"], str(raw["version"]), raw.get("path", ""))
            validate_name(r.schema, what="引用 Schema 名称")
            record = self.get_schema(r.schema, r.version)
            if r.path and not r.path.startswith("/"):
                raise ValueError(f"资产引用字段路径必须是 JSON Pointer: {r.path!r}")
            candidate_paths = []
            contextual = ptr.resolve_logical(record.document, r.path)
            if contextual is not None:
                candidate_paths.append(contextual)
            text_normalized = ptr.normalize_field_pointer(r.path)
            for cand in (text_normalized, r.path):
                if cand not in candidate_paths:
                    candidate_paths.append(cand)

            resolved_path = next(
                (
                    cand
                    for cand in candidate_paths
                    if self._logical_path_exists(
                        r.schema, r.version, cand, frozenset({(r.schema, r.version)})
                    )
                ),
                None,
            )
            if resolved_path is None:
                raise NotFoundError(
                    f"资产引用的字段 {r.schema}@{r.version}{text_normalized} 不存在",
                    details={
                        "schema": r.schema,
                        "version": r.version,
                        "path": text_normalized,
                    },
                )
            r = FieldRef(r.schema, r.version, resolved_path)
            dedup_key = (r.schema, r.version, r.path)
            if dedup_key in seen:
                continue
            seen.add(dedup_key)
            normalized.append(r)

        normalized.sort(key=lambda r: (r.schema, r.version, r.path))
        asset = Asset(asset_id, name, kind, tuple(normalized))
        self._assets[asset_id] = asset
        return asset

    def get_asset(self, asset_id: str) -> Asset:
        if asset_id not in self._assets:
            raise NotFoundError(f"资产 {asset_id} 不存在", details={"asset": asset_id})
        return self._assets[asset_id]

    def all_assets(self) -> list[Asset]:
        return [self._assets[k] for k in sorted(self._assets)]

"""字段路径工具。

字段路径采用 JSON Pointer（RFC 6901）表示，例如 ``/properties/name``、
``/properties/a~1b``。根对象本身用空串 ``""`` 表示。
"""

from __future__ import annotations

from typing import Any


def escape(token: str) -> str:
    """转义单个路径段。"""
    return token.replace("~", "~0").replace("/", "~1")


def unescape(token: str) -> str:
    """反转义单个路径段。"""
    return token.replace("~1", "/").replace("~0", "~")


def parse(path: str) -> tuple[str, ...]:
    """把 JSON Pointer 解析为路径段元组；根路径返回空元组。"""
    if path == "":
        return ()
    if not path.startswith("/"):
        raise ValueError(f"非法 JSON Pointer: {path!r}")
    return tuple(unescape(seg) for seg in path[1:].split("/"))


def format(segments: tuple[str, ...] | list[str]) -> str:
    """把路径段组装为 JSON Pointer。"""
    return "".join("/" + escape(str(seg)) for seg in segments)


def child(path: str, segment: str) -> str:
    """返回某路径下的子路径。"""
    return (path + "/" + escape(segment)) if path else "/" + escape(segment)


def parent(path: str) -> str | None:
    """返回父路径；根路径返回 ``None``。"""
    segs = parse(path)
    if not segs:
        return None
    return format(segs[:-1])


def is_under(prefix: str, path: str) -> bool:
    """``path`` 是否位于 ``prefix`` 子树内（含自身）。"""
    p, c = parse(prefix), parse(path)
    return len(c) >= len(p) and c[: len(p)] == p


def resolve(doc: Any, path: str) -> Any:
    """在文档中按 JSON Pointer 取值，缺段/越界/类型不符时抛 KeyError。"""
    cur: Any = doc
    for seg in parse(path):
        if isinstance(cur, dict):
            if seg not in cur:
                raise KeyError(path)
            cur = cur[seg]
        elif isinstance(cur, list):
            try:
                idx = int(seg)
            except ValueError as exc:
                raise KeyError(path) from exc
            if not 0 <= idx < len(cur):
                raise KeyError(path)
            cur = cur[idx]
        else:
            raise KeyError(path)
    return cur


def normalize_field_pointer(path: str) -> str:
    """把 Schema 文档指针 *无上下文地* 规整为逻辑字段路径。

    注意：纯文本规整无法区分「名为 ``items`` 的属性」与 ``items`` 关键字，
    资产/引用路径应优先使用逻辑路径，或用 :func:`resolve_logical` 结合
    文档解析。
    """
    segs = list(parse(path))
    out: list[str] = []
    for i, seg in enumerate(segs):
        if seg in ("properties", "prefixItems"):
            continue
        if seg == "additionalProperties":
            out.append("*")
        elif seg == "items":
            # 元组形式 items/0 展开为数组下标；单 Schema items 展开为 -。
            if i + 1 < len(segs) and segs[i + 1].isdigit():
                continue
            out.append("-")
        else:
            out.append(seg)
    return format(out)


def resolve_logical(document: Any, raw_path: str) -> str | None:
    """结合文档结构，把文档指针解析为逻辑字段路径；不可解析返回 ``None``。

    遍历规则与字段展开一致：``properties`` 段省略（其后必为属性名，即使
    名字恰好叫 ``items``）；单 Schema ``items`` 段映射为 ``-``；
    ``additionalProperties`` 映射为 ``*``；``$defs``/``definitions`` 保留。
    """
    segs = parse(raw_path)
    node: Any = document
    logical: list[str] = []
    i = 0
    while i < len(segs):
        seg = segs[i]
        if isinstance(node, dict):
            props = node.get("properties")
            if seg == "properties" and isinstance(props, dict):
                # 容器关键字与其后的属性名在同一步消费，避免属性名与
                # Schema 关键字（如名为 items 的属性）混淆。
                if i + 1 >= len(segs):
                    return None
                name = segs[i + 1]
                if name not in props:
                    return None
                node = props[name]
                logical.append(name)
                i += 2
                continue
            pats = node.get("patternProperties")
            if seg == "patternProperties" and isinstance(pats, dict):
                if i + 1 >= len(segs):
                    return None
                name = segs[i + 1]
                if name not in pats:
                    return None
                node = pats[name]
                logical.append(escape(name))
                i += 2
                continue
            ap = node.get("additionalProperties")
            if seg == "additionalProperties" and isinstance(ap, (dict, bool)):
                node = ap
                logical.append("*")
                i += 1
                continue
            items = node.get("items")
            if seg == "items" and isinstance(items, (dict, bool)):
                node = items
                logical.append("-")
                i += 1
                continue
            pre = node.get("prefixItems")
            if seg == "prefixItems" and isinstance(pre, list):
                if i + 1 >= len(segs):
                    return None
                try:
                    idx = int(segs[i + 1])
                except ValueError:
                    return None
                if not 0 <= idx < len(pre):
                    return None
                node = pre[idx]
                logical.append(str(idx))
                i += 2
                continue
            if seg in ("$defs", "definitions") and isinstance(node.get(seg), dict):
                if i + 1 >= len(segs):
                    return None
                name = segs[i + 1]
                if name not in node[seg]:
                    return None
                node = node[seg][name]
                logical.extend((seg, name))
                i += 2
                continue
            if seg not in node:
                return None
            node = node[seg]
            logical.append(seg)
            i += 1
        elif isinstance(node, list):
            try:
                idx = int(seg)
            except ValueError:
                return None
            if not 0 <= idx < len(node):
                return None
            node = node[idx]
            logical.append(seg)
            i += 1
        else:
            return None
    return format(logical)

"""按字段集合的批量影响分析（``analyze_impact_batch``）。

在单字段影响分析（:func:`meta_catalog.impact.analyze_field`）的命中口径之上，
按一组逻辑字段筛选受影响资产：

  * ``any`` 模式：资产至少命中一个字段即入选；
  * ``all`` 模式：资产必须命中每一个字段才入选。

字段按首次出现顺序去重；可选资产标识列表去重后限定候选范围，缺省覆盖全部
资产，空列表不选任何资产。每个入选资产给出 ``matched_fields``（按输入顺序
的实际命中字段）与逐字段明细 ``fields``：命中方式（``direct`` /
``transitive`` / ``both``）、与单字段分析同口径的直接信息与传递引用证据
（证据按稳定路径去重排序，根字段与父子字段沿用既有包含关系）。

本模块只读注册簿：不注册资源、不生成报告、不写入检索索引；相同输入返回
相同结构，返回值不与注册内容共享可变引用。
"""

from __future__ import annotations

from typing import Any

from . import limits
from . import pointer as ptr
from .errors import (
    ImpactAnalysisInvalid,
    ImpactAnalysisTooLarge,
    NotFoundError,
)
from .impact import analyze_field
from .registry import Registry

_MODES = ("all", "any")


def analyze_impact_batch(registry: Registry, request: Any) -> dict[str, Any]:
    """按字段集合筛选受影响资产（只读，不改动任何注册内容）。"""
    schema, version, paths, mode, candidate_ids = _validate_request(registry, request)

    # 空候选（asset_ids=[]）直接返回空资产集合，不做任何链式解析。
    if not candidate_ids:
        return _result(
            schema, version, paths, mode,
            0, {p: set() for p in paths}, set(), [],
        )

    candidate_set = set(candidate_ids)

    # 逐字段做单字段影响分析（与 analyze_impact 完全同口径，含链深、引用边
    # 与单字段影响资产数限制），再把命中限定到候选范围。
    direct_by_field: dict[str, dict[str, dict]] = {}
    transitive_by_field: dict[str, dict[str, list[dict]]] = {}
    hits_by_field: dict[str, set[str]] = {}
    for path in paths:
        impacts = analyze_field(registry, schema, version, path)
        direct = {
            a["asset_id"]: a
            for a in impacts["direct_assets"]
            if a["asset_id"] in candidate_set
        }
        transitive: dict[str, list[dict]] = {}
        for a in impacts["transitive_assets"]:
            if a["asset_id"] in candidate_set:
                transitive.setdefault(a["asset_id"], []).append(a)
        direct_by_field[path] = direct
        transitive_by_field[path] = transitive
        hits_by_field[path] = set(direct) | set(transitive)

    union_ids: set[str] = set()
    for path in paths:
        union_ids |= hits_by_field[path]
    if len(union_ids) > limits.MAX_IMPACT_ASSETS:
        raise ImpactAnalysisTooLarge(
            "入选资产数量超过公开限制",
            details={"reason": "assets_exceeded", "limit": limits.MAX_IMPACT_ASSETS},
        )

    if mode == "all":
        final_ids = set(hits_by_field[paths[0]])
        for path in paths[1:]:
            final_ids &= hits_by_field[path]
    else:
        final_ids = union_ids

    assets_by_id = {a.id: a for a in registry.all_assets()}
    entries: list[dict[str, Any]] = []
    for aid in sorted(final_ids):
        asset = assets_by_id[aid]
        matched = [p for p in paths if aid in hits_by_field[p]]
        fields_detail: dict[str, Any] = {}
        has_direct = False
        has_transitive = False
        for path in matched:
            direct = direct_by_field[path].get(aid)
            evidence = transitive_by_field[path].get(aid, [])
            is_direct = direct is not None
            is_transitive = bool(evidence)
            has_direct = has_direct or is_direct
            has_transitive = has_transitive or is_transitive
            fields_detail[path] = {
                "impact_kind": _impact_kind(is_direct, is_transitive),
                "direct": (
                    {
                        "asset_id": direct["asset_id"],
                        "name": direct["name"],
                        "kind": direct["kind"],
                    }
                    if is_direct
                    else None
                ),
                "transitive": [
                    {
                        "schema": e["schema"],
                        "version": e["version"],
                        "path": e["path"],
                        "matched_paths": list(e["matched_paths"]),
                    }
                    for e in evidence
                ],
            }
        entries.append(
            {
                "asset_id": asset.id,
                "name": asset.name,
                "kind": asset.kind,
                "matched_fields": matched,
                "fields": fields_detail,
                "impact_kind": _impact_kind(has_direct, has_transitive),
            }
        )

    return _result(
        schema, version, paths, mode,
        len(candidate_ids), hits_by_field, union_ids, entries,
    )


def _impact_kind(has_direct: bool, has_transitive: bool) -> str:
    if has_direct and has_transitive:
        return "both"
    return "direct" if has_direct else "transitive"


def _result(
    schema: str,
    version: str,
    paths: list[str],
    mode: str,
    candidate_count: int,
    hits_by_field: dict[str, set[str]],
    union_ids: set[str],
    entries: list[dict[str, Any]],
) -> dict[str, Any]:
    return {
        "schema": schema,
        "version": version,
        "paths": list(paths),
        "mode": mode,
        "summary": {
            "candidate_assets": candidate_count,
            "selected_assets": len(union_ids),
            "field_hits": {p: len(hits_by_field[p]) for p in paths},
            "matched_assets": len(entries),
        },
        "assets": entries,
    }


def _validate_request(
    registry: Registry, request: Any
) -> tuple[str, str, list[str], str, list[str]]:
    """结构校验（ImpactAnalysisInvalid）与存在性校验（NotFoundError）。

    返回 ``(schema, version, 去重后路径, mode, 候选资产标识升序列表)``；
    校验失败不返回任何部分结果。
    """
    if not isinstance(request, dict):
        raise ImpactAnalysisInvalid(
            "请求必须是字典", details={"reason": "request_not_mapping"}
        )

    schema = request.get("schema")
    if not isinstance(schema, str) or not schema:
        raise ImpactAnalysisInvalid(
            "schema 必须是非空字符串", details={"reason": "invalid_schema"}
        )
    version = request.get("version")
    if not isinstance(version, str) or not version:
        raise ImpactAnalysisInvalid(
            "version 必须是非空字符串", details={"reason": "invalid_version"}
        )

    raw_paths = request.get("paths")
    if not isinstance(raw_paths, list) or any(
        not isinstance(p, str) for p in raw_paths
    ):
        raise ImpactAnalysisInvalid(
            "paths 必须是字符串列表", details={"reason": "invalid_paths"}
        )

    mode = request.get("mode")
    if mode not in _MODES:
        raise ImpactAnalysisInvalid(
            f"mode 必须是 all 或 any: {mode!r}",
            details={"reason": "invalid_mode", "mode": mode},
        )

    asset_ids = request.get("asset_ids")
    if asset_ids is not None and (
        not isinstance(asset_ids, list)
        or any(not isinstance(a, str) or not a for a in asset_ids)
    ):
        raise ImpactAnalysisInvalid(
            "asset_ids 必须是非空字符串列表",
            details={"reason": "invalid_asset_ids"},
        )

    paths: list[str] = []
    seen: set[str] = set()
    for path in raw_paths:
        try:
            ptr.parse(path)
        except ValueError as exc:
            raise ImpactAnalysisInvalid(
                f"路径不是合法逻辑 JSONPointer: {path!r}",
                details={"reason": "invalid_pointer", "path": path},
            ) from exc
        if path not in seen:
            seen.add(path)
            paths.append(path)
    if not paths:
        raise ImpactAnalysisInvalid(
            "去重后的字段集合为空", details={"reason": "empty_paths"}
        )

    # 存在性校验放在结构校验之后：未知 Schema/版本/字段抛 NotFoundError。
    registry.get_schema(schema, version)
    for path in paths:
        if not registry.logical_path_exists(schema, version, path):
            raise NotFoundError(
                f"字段 {schema}@{version}{path} 不可达",
                details={"schema": schema, "version": version, "path": path},
            )

    if asset_ids is None:
        candidates = [a.id for a in registry.all_assets()]
    else:
        candidates = sorted(set(asset_ids))
