c = MetaCatalog()
# candidate /location 只保留 lat：/geo/lng 的深层引用映射目标不可达 -> target_deleted
c.register_schema("Address", "1.0", {
    "type": "object",
    "properties": {
        "geo": {"type": "object", "properties": {
            "lat": {"type": "number"}, "lng": {"type": "number"}}},
    },
})
c.register_schema("Address", "2.0", {
    "type": "object",
    "properties": {
        "location": {"type": "object", "properties": {"lat": {"type": "number"}}},
    },
})
c.register_schema("Holder", "1.0", {
    "type": "object",
    "properties": {"g": {"$ref": "Address@1.0#/properties/geo"}},
})
c.register_asset("a-lng", "经度", "service",
                 [{"schema": "Address", "version": "1.0", "path": "/geo/lng"}])
c.register_asset("a-geo", " geo", "service",
                 [{"schema": "Address", "version": "1.0", "path": "/geo"}])

plan = c.plan_reference_migration("Address", "1.0", "2.0",
                                  renames=[{"from": "/geo", "to": "/location"}])
for e in plan["references"]:
    print(e["source_type"], e["source_schema"] or e["asset_id"],
          e["target_path"], "->", e["status"], e["reason"], e["suggested_path"])
print(json.dumps(plan["summary"], ensure_ascii=False))

# 同一 Schema 高版本回指基线版本，也应计入来源
c.register_schema("Address", "3.0", {
    "type": "object",
    "properties": {"prev": {"$ref": "Address@1.0#/properties/geo"}},
})
plan2 = c.plan_reference_migration("Address", "1.0", "2.0",
                                   renames=[{"from": "/geo", "to": "/location"}])
print(plan2["summary"])
